export function PixelWord({
  word,
  className = '',
  style,
  opacity,
}: {
  word: PixelWordType;
  className?: string;
  style?: React.CSSProperties;
  opacity?: number;
}) {
  const data = PIXEL_WORDS[word];
  if (!data) return null;

  return (
    <svg
      viewBox={data.viewBox}
      width={data.width}
      height={data.height}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden="true"
      className={`pb-pixel-word select-none pointer-events-none ${className}`}
      style={{ opacity, ...style }}
    >
      {data.blocks.map((b: { x: number; y: number; lit: boolean }, i: number) => {
        const s = 8;
        return (
          <g key={i}>
            <rect x={b.x + 1} y={b.y + 3} width={s} height={s} rx={1.2} fill="#9b3d06" />
            <rect x={b.x} y={b.y + 1} width={s} height={s - 1} rx={1.2} fill="#f99419" />
            <rect x={b.x} y={b.y} width={s} height={s - 3} rx={1.2} fill={b.lit ? '#fff17a' : '#ffda35'} />
            <rect x={b.x + 1} y={b.y + 1} width={Math.max(1, s - 3)} height={1.2} fill="#ffed6a" opacity={0.9} />
          </g>
        );
      })}
    </svg>
  );
}
